import { ChangeDetectorRef, Component, Inject } from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatTableModule } from '@angular/material/table';
import { animate, state, style, transition, trigger } from '@angular/animations';
import { OcrqueueService } from '../../../services/ocrqueue/ocrqueue.service';
import { caseDetailOCR, userDetailOCR } from '../../../interfaces/ocrqueue.interface';
import { CommonModule } from '@angular/common';
import { UploadService } from '../../../services/upload/upload.service';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';

@Component({
  selector: 'app-ocrlist',
  standalone: true,
  imports: [CommonModule, IconComponent, MatSelectModule, FormsModule, MatTableModule, EmptyComponent],
  templateUrl: './ocrlist.component.html',
  styleUrl: './ocrlist.component.scss',
  animations: [
    trigger('detailExpand', [
      state('collapsed,void', style({ height: '0px', minHeight: '0' })),
      state('expanded', style({ height: '*' })),
      transition('expanded <=> collapsed', animate('225ms cubic-bezier(0.4, 0.0, 0.2, 1)')),
    ]),
  ]
})
export class OcrlistComponent {
  socketSubscription: Subscription;
  caselist: caseDetailOCR[] = [];
  uselist: userDetailOCR[] = [];
  dataSource;
  columnsToDisplay = ['cn', 'un', 'fn', 's', 'st', 'te'];
  columnsToDisplayWithExpand = [...this.columnsToDisplay, 'expand'];
  expandedElement: null;
  nUserid: string= null;
  nCaseid: string= null;
  constructor(@Inject(OcrqueueService) private orcqueueS: OcrqueueService, private upld: UploadService, private ss: SocketService,
    private cdr: ChangeDetectorRef
  ) {

    this.socketSubscription = this.ss.getUploades().subscribe(async (res: any) => {
      let filelist: any;
      let cStatus = '';
      if (res && res.event && ['OCR-START', 'OCR-PROGRESS', 'OCR-SUCCESS', 'OCR-ERROR'].includes(res.event)) {
        loop1: for (let e of this.caselist) {
          for (let f of e.filelist) {
            if (f.nUDid == res.data.nUDid) {
              filelist = f;
              break loop1;
            }
          }
        }
        cStatus = res.event == 'OCR-START' ? 'OI' : res.event == 'OCR-PROGRESS' ? 'OP' : res.event == 'OCR-SUCCESS' ? 'OS' : res.event == 'OCR-ERROR' ? 'OF' : '';
      }
      if (filelist) {
        if (cStatus == 'OS' || cStatus == 'OF' || cStatus == 'OI') {
          if (filelist && filelist.ocrFiles && filelist.ocrFiles.length > 0) {
            filelist.ocrFiles.map((a) => {
              if (a.id == parseInt(res.data.id)) {
                a.cStatus = cStatus == 'OI' ? 'P' : cStatus == 'OS' ? 'C' : 'F';
                a.message = null;
                if (cStatus == 'OS') { filelist.nCompleted++; filelist.nOProgress-- }
                if (cStatus == 'OI') { filelist.nOProgress++ }
                if (cStatus == 'OF') { filelist.nFailed++; filelist.nOProgress-- }
              }
            })
          }
        }
        if (cStatus == 'OP') {
          if (filelist && filelist.ocrFiles && filelist.ocrFiles.length > 0) {
            filelist.ocrFiles.map((a) => {
              if (a.id == parseInt(res.data.id)) {
                a.message = res.data.message ? res.data.message : null;
              }
            })
          }
        }
      }
    });
  }


  ngOnInit(): void {
    this.getOcrList();
  }

  async getOcrList() {
    let res = await this.orcqueueS.get_ocrlist(this.nCaseid, this.nUserid);
    if (res.length) {
      this.caselist = res[0];
      this.uselist = res[1];
    }
  }

  async getOcrUploadlist(row) {
    debugger;
    if (row.expand) { row.expand = !row.expand; return };
    row.expand = !row.expand
    row.loading = true
    let res = await this.orcqueueS.get_ocrFilelist(row.nCaseid, this.nUserid);
    row.loading = false
    if (res.length) {
      row.filelist = res;
    } else {
      row.filelist = [];
    }
  }

  getOCRFiles(element) {
    if (this.expandedElement != element) {
      this.orcqueueS.getFileData(element.nUDid, element);
    }
  }


  getTime(row) {
    // Get the current timestamp
    const now: any = row.dStartDt ? new Date(row.dStartDt) : null;
    if (!now) {
      return '';
    }
    else {
      let endDt = row.dEndDt
      const oneDayAgo: any = endDt ? new Date(endDt) : new Date();

      // Calculate the time difference in milliseconds
      const diffMilliseconds = oneDayAgo - now;

      // Convert milliseconds to seconds
      const diffSeconds = Math.floor(diffMilliseconds / 1000);

      // Calculate total minutes and remaining seconds
      const totalMinutes = Math.floor(diffSeconds / 60);
      const totalSeconds = diffSeconds % 60;
      return `${totalMinutes} minute ${totalSeconds} second`;
    }
    // Subtract 1 day (24 hours) from now



  }


}