import { Injectable } from '@angular/core';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { caseDetailOCR, ocrfileList } from '../../interfaces/ocrqueue.interface';
import { ocrFiles, ocrUDid } from '../../interfaces/upload.interface';

@Injectable({
  providedIn: 'root'
})
export class OcrqueueService {
  constructor(public sStore: SecureStorageService, private http: HttpClient) { }



  async get_ocrlist(nCaseid, nUserid): Promise<any> {
    try {
      let params = {
        nCaseid: nCaseid,
        nUserid: nUserid
      }
      const res = await firstValueFrom(
        this.http.get<any>(`${environment.cloudUrl}${environment.coreservice}/ocrqueue/get_ocrlist`, { params: params })
      );
      return res
    } catch (err) {
      return [];
    }
  }


  async get_ocrFilelist(nCaseid, nUserid): Promise<ocrfileList[]> {
    try {
      let params = {
        nCaseid: nCaseid,
        nUserid: nUserid
      }
      const res = await firstValueFrom(
        this.http.get<ocrfileList[]>(`${environment.cloudUrl}${environment.coreservice}/ocrqueue/get_ocrfilelist`, { params: params })
      );
      return res
    } catch (err) {
      return [];
    }
  }


  async getFileData(nUDid, file) {
    console.log('getFileData', nUDid)
    if (nUDid) {
      let res = await this.fetchOCRDate(nUDid);
      let res1: ocrUDid = res && res.length ? res[0][0] : []
      let res2: ocrFiles[] = res && res.length && res.length > 1 ? res[1] : []
      debugger;
      if (res1) {
        if (res1.nOCRFiles == res1.nCompleted) {
          file.nOProgress = 0;
          file.nCompleted = res1.nCompleted;
          // file.ocrFiles = []
        } else {
          if (file.cFiletype != 'ZIP') {
            file.nFiles = res1.nOCRFiles;
          }
          file.nOProgress = res1.nOProgress;
          file.nOCRFiles = res1.nOCRFiles;
          file.nCompleted = res1.nCompleted;
          file.nFailed = res1.nFailed;
          file.ocrFiles = res2
        }
      }
    }
    // return ''
  }


  async fetchOCRDate(nUDid: string): Promise<any> {
    try {
      const params = new HttpParams().set('nUDid', nUDid);
      const res: any = await firstValueFrom(
        this.http.get<any>(`${environment.cloudUrl}${environment.coreservice}/upload/ocrdata`, { params: params })
      );
      return res;
    } catch (err) {
      return [];
    }
  }
}
